#include <algorithm>
#include <fstream>
#include <set>
#include <string>
#include <vector>
using namespace std;
int main() {
    ifstream in("tttt.in");
    ofstream out("tttt.out");
    vector<string> board(3), lines;
    for (string &row : board) in >> row;
    lines = board;
    for (int column = 0; column < 3; ++column) {
        string line;
        for (int row = 0; row < 3; ++row) line += board[row][column];
        lines.push_back(line);
    }
    string diagonal, reverse_diagonal;
    for (int i = 0; i < 3; ++i) {
        diagonal += board[i][i];
        reverse_diagonal += board[i][2 - i];
    }
    lines.push_back(diagonal);
    lines.push_back(reverse_diagonal);
    set<char> individuals;
    set<string> teams;
    for (string line : lines) {
        sort(line.begin(), line.end());
        line.erase(unique(line.begin(), line.end()), line.end());
        if (line.size() == 1) individuals.insert(line[0]);
        if (line.size() == 2) teams.insert(line);
    }
    out << individuals.size() << '\n' << teams.size() << '\n';
}
