#include <fstream>
#include <vector>
using namespace std;
int main() {
    ifstream in("milkorder.in");
    ofstream out("milkorder.out");
    int n, m, k;
    in >> n >> m >> k;
    vector<int> hierarchy(m), position(n + 1, 0), reserved(n + 1, 0);
    for (int &cow : hierarchy) in >> cow;
    for (int i = 0; i < k; ++i) {
        int cow, place;
        in >> cow >> place;
        position[cow] = place;
        reserved[place] = cow;
    }
    for (int candidate = 1; candidate <= n; ++candidate) {
        if (position[1] != 0 && position[1] != candidate) continue;
        if (reserved[candidate] != 0 && reserved[candidate] != 1) continue;
        vector<int> slots = reserved, anchors = position;
        slots[candidate] = 1;
        anchors[1] = candidate;
        int cursor = 0;
        bool valid = true;
        for (int cow : hierarchy) {
            int place;
            if (anchors[cow] != 0) {
                place = anchors[cow];
                if (place <= cursor) { valid = false; break; }
            } else {
                place = cursor + 1;
                while (place <= n && slots[place] != 0) ++place;
                if (place > n) { valid = false; break; }
                slots[place] = cow;
            }
            cursor = place;
        }
        if (valid) { out << candidate << '\n'; return 0; }
    }
}
