#include <fstream>
#include <map>
#include <string>
using namespace std;
string ancestral_relation(int generations) {
    if (generations == 1) return "mother";
    string relation;
    for (int i = 0; i < generations - 2; ++i) relation += "great-";
    return relation + "grand-mother";
}
string aunt_relation(int descendant_distance) {
    string relation;
    for (int i = 0; i < descendant_distance - 2; ++i) relation += "great-";
    return relation + "aunt";
}
int main() {
    ifstream in("family.in");
    ofstream out("family.out");
    int n;
    string first, second;
    in >> n >> first >> second;
    map<string, string> parent;
    for (int i = 0; i < n; ++i) {
        string mother, child;
        in >> mother >> child;
        parent[child] = mother;
    }
    map<string, int> first_distance;
    string current = first;
    int distance = 0;
    while (true) {
        first_distance[current] = distance;
        auto it = parent.find(current);
        if (it == parent.end()) break;
        current = it->second;
        ++distance;
    }
    current = second;
    int second_distance = 0;
    while (first_distance.count(current) == 0) {
        auto it = parent.find(current);
        if (it == parent.end()) { out << "NOT RELATED\n"; return 0; }
        current = it->second;
        ++second_distance;
    }
    int a = first_distance[current], b = second_distance;
    if (a == 0) out << first << " is the " << ancestral_relation(b) << " of " << second << '\n';
    else if (b == 0) out << second << " is the " << ancestral_relation(a) << " of " << first << '\n';
    else if (a == 1 && b == 1) out << "SIBLINGS\n";
    else if (a == 1) out << first << " is the " << aunt_relation(b) << " of " << second << '\n';
    else if (b == 1) out << second << " is the " << aunt_relation(a) << " of " << first << '\n';
    else out << "COUSINS\n";
}
